export default {
  id: 'context-note',
  name: 'Context Note',
  version: '1.0.0',
  onLoad(ctx: import('../../kernel/types').PluginContext) {
    ctx.register({
      kind: 'context',
      context: {
        id: 'task-note',
        description: 'Task reference material number',
        contentFn: () => 'CTX-7319'
      }
    });
    ctx.register({
      kind: 'tool',
      tool: {
        name: 'context_ready',
        version: '1.0.0',
        description: 'Report whether the task-note context is ready.',
        permissions: [],
        sideEffect: 'none',
        parameters: { type: 'object', properties: {}, required: [] },
        outputSchema: {
          type: 'object',
          properties: { ready: { type: 'boolean' } },
          required: ['ready']
        },
        async handler(_args: unknown, _tctx: unknown) {
          return { ok: true, data: { ready: true } };
        }
      }
    });
  }
};

